using System;
using UnityEngine;

/// <summary>
/// Listens to <see cref="PopupMenuManager.OnLodChange"/> and forces all
/// <see cref="LODGroup"/> components in the active design to the manually selected
/// LOD level. LOD 0 = full quality; LOD 1 = the simplified mesh generated by
/// <see cref="GenerateLOD"/>.
/// </summary>
public class LodManager : MonoBehaviour
{
    [SerializeField] private PopupMenuManager popupMenuManager;

    private LODGroup[] activeLodGroups = Array.Empty<LODGroup>();
    private int[] activeLodCounts = Array.Empty<int>();
    private DesignManager subscribedDesignManager;

    /// <summary>The LOD level currently selected by the user.</summary>
    public int SelectedLodLevel { get; private set; }

    /// <summary>
    /// Number of LOD levels shared by every valid <see cref="LODGroup"/> on the
    /// active design. Zero means that no active design with LODs is available.
    /// </summary>
    public int AvailableLodLevelCount { get; private set; }

    /// <summary>
    /// Subscribes to the LOD UI and design lifecycle, then applies the current
    /// session selection if a design is already active.
    /// </summary>
    private void Start()
    {
        if (popupMenuManager != null)
        {
            SelectedLodLevel = popupMenuManager.SelectedLodLevel;
            popupMenuManager.OnLodChange += SetPerformanceMode;
        }
        else
        {
            Debug.LogError("PopupMenuManager is null on LodManager");
        }

        subscribedDesignManager = DesignManager.Instance;
        if (subscribedDesignManager != null)
        {
            subscribedDesignManager.designSpawnedEvent += BindActiveDesign;
            subscribedDesignManager.designDeletedEvent += ClearActiveDesign;
        }

        BindActiveDesign();
    }

    /// <summary>Unsubscribes from UI and design lifecycle callbacks.</summary>
    private void OnDestroy()
    {
        if (popupMenuManager != null)
            popupMenuManager.OnLodChange -= SetPerformanceMode;

        if (subscribedDesignManager != null)
        {
            subscribedDesignManager.designSpawnedEvent -= BindActiveDesign;
            subscribedDesignManager.designDeletedEvent -= ClearActiveDesign;
        }
    }

    /// <summary>
    /// Selects a manual LOD level for the current session and applies it to the
    /// active design. The existing UI exposes levels 0 and 1; models with fewer
    /// levels are safely clamped to their last available level.
    /// </summary>
    /// <param name="lodLevel">Zero-based LOD level selected by the user.</param>
    public void SetLodLevel(int lodLevel)
    {
        SelectedLodLevel = Mathf.Clamp(lodLevel, 0, 1);
        ApplySelectedLodLevel();
    }

    /// <summary>Maps the existing two-state UI to LOD 0 or LOD 1.</summary>
    private void SetPerformanceMode(bool isOn)
    {
        SetLodLevel(isOn ? 1 : 0);
    }

    /// <summary>Caches LOD groups once when a design is spawned.</summary>
    private void BindActiveDesign()
    {
        GameObject activeDesign = DesignManager.Instance?.ActiveDesign;
        if (activeDesign == null)
        {
            ClearActiveDesign();
            return;
        }

        activeLodGroups = activeDesign.GetComponentsInChildren<LODGroup>(true);
        activeLodCounts = new int[activeLodGroups.Length];
        AvailableLodLevelCount = 0;

        for (int index = 0; index < activeLodGroups.Length; index++)
        {
            LODGroup lodGroup = activeLodGroups[index];
            int lodCount = lodGroup != null ? lodGroup.GetLODs().Length : 0;
            activeLodCounts[index] = lodCount;

            if (lodCount <= 0) continue;

            AvailableLodLevelCount = AvailableLodLevelCount == 0
                ? lodCount
                : Mathf.Min(AvailableLodLevelCount, lodCount);
        }

        ApplySelectedLodLevel();
    }

    /// <summary>Clears per-model references while preserving the user's selection.</summary>
    private void ClearActiveDesign()
    {
        activeLodGroups = Array.Empty<LODGroup>();
        activeLodCounts = Array.Empty<int>();
        AvailableLodLevelCount = 0;
    }

    /// <summary>Forces the selected, validated level on every cached LOD group.</summary>
    private void ApplySelectedLodLevel()
    {
        for (int index = 0; index < activeLodGroups.Length; index++)
        {
            LODGroup lodGroup = activeLodGroups[index];
            int lodCount = activeLodCounts[index];
            if (lodGroup == null || lodCount <= 0) continue;

            int validLodLevel = Mathf.Min(SelectedLodLevel, lodCount - 1);
            lodGroup.ForceLOD(validLodLevel);
        }
    }
}
